uint baseHash(uvec2 p)
{
    p = 1103515245U*((p >> 1U)^(p.yx));
    uint h32 = 1103515245U*((p.x)^(p.y>>3U));
    return h32^(h32 >> 16);
}

vec2 hash22(vec2 x)
{
    uint n = baseHash(floatBitsToUint(x));
    uvec2 rz = uvec2(n, n*48271U);
    return vec2((rz.xy >> 1) & uvec2(0x7fffffffU))/float(0x7fffffff);
}

vec4 nyan(vec2 uv, int frame) {
    uv = clamp(uv, 0.0, 1.0);

    uv *= vec2(40,32);

    if (frame < 2) uv.y -= 1.0;

    uv.x += float(frame) * 40.0;

    return texelFetch(iChannel0, ivec2(uv), 0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / vec2(40,32);

    uv.x -= iTime * 2.0;

    vec3 col = vec3(0.0, 0.2, 0.4);

    for (int x = -1; x < 1; x++) {
        for (int y = -1; y < 1; y++) {
            vec2 cellUV = fract(uv) - vec2(x, y);

            vec2 rand = hash22(floor(uv) + vec2(x, y));

            vec4 cat = nyan(cellUV - rand, int(iTime * 12.0) % 6);

            col = mix(col, cat.rgb, cat.a);
        }
    }

    // Output to screen
    fragColor = vec4(col,1.0);
}
